std::unordered_map<std::string, int> m;

// Problem: The map's element type is std::pair<const std::string, int>.
// The declared type 'p' is missing the 'const' on the key.
// This forces the compiler to create a temporary copy for each element.
for (const std::pair<std::string, int>& p : m)
{
  // 'p' is a reference to a temporary, not an element in 'm'.
}

// Correct: 'auto' deduces the exact element type.
// 'p' is now a reference directly to an element in 'm'. No copies are made.
for (const auto& p : m)
{
  // ...
}
